from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import object
from abc import ABCMeta, abstractmethod
from future import standard_library
from future.utils import with_metaclass
standard_library.install_aliases()


class ToolBase(with_metaclass(ABCMeta, object)):

    TOOL = None

    @abstractmethod
    def traffic_capture_start(self, **kwargs):
        pass

    @abstractmethod
    def traffic_capture_stop(self, **kwargs):
        pass

    #@abstractmethod
    def traffic_capture_abort(self, **kwargs):
        pass

    #@abstractmethod
    def upload_traffic_capture_file(self, **kwargs):
        pass

    #@abstractmethod
    def generate_capture_files(self, **kwargs):
        pass

    @classmethod
    def check_tool(cls, tool):
        # logger.debug(" In check tool")
        return tool == cls.TOOL
